import {
  createBlobZipSource,
  createWebZipCompressionCodec,
  iterateZipStreamChunks,
  StreamingZipReader,
  StreamingZipWriter,
  type ZipArchiveEntry,
} from '@/utils/zip-stream';
import { createAbortableByteStream } from '@/utils/abortable-byte-stream';
import { createMemoryZipCentralDirectoryStore, createReadableZipOutput } from '@/utils/zip-stream/memory';

/** Evidence owns immutable file contents; ZIP is only its transport encoding. */
export interface EvidenceArchiveReader {
  readonly paths: readonly string[];
  read({ path, maximumBytes }: { path: string; maximumBytes?: number }): Promise<Blob | undefined>;
}

function validateEvidencePath({ path }: { path: string }): void {
  if (path.length === 0 || path.includes('\\') || path.includes('\0')
    || path.split('/').some(part => part === '' || part === '.' || part === '..')) {
    throw new Error('Invalid Evidence archive path');
  }
}

export function setEvidenceFile({ files, path, content }: {
  files: Map<string, Blob>; path: string; content: BlobPart;
}): void {
  validateEvidencePath({ path });
  // Snapshot mutable byte views at insertion, before any compression/hash await.
  // Blob parts share immutable storage; they do not become mutable typed arrays.
  files.set(path, new Blob([content]));
}

export function createEvidenceFilesReader({ files }: {
  files: ReadonlyMap<string, Blob>;
}): EvidenceArchiveReader {
  const owned = new Map(files);
  return {
    paths: [...owned.keys()],
    async read({ path, maximumBytes }) {
      const file = owned.get(path);
      if (file !== undefined && maximumBytes !== undefined && file.size > maximumBytes) throw new Error('Evidence entry exceeds its read byte budget');
      return file;
    },
  };
}

export interface PreparedEvidenceArchive {
  files: ReadonlyMap<string, Blob>;
  fileName: string;
}

/** ZIP output is bounded and demand-driven; immutable input files stay shared. */
export function createEvidenceArchiveStream({ files }: {
  files: ReadonlyMap<string, Blob>;
}): ReadableStream<Uint8Array> {
  const owned = [...files.entries()];
  // ZIP64 is not supported by the existing ZIP reader/writer.
  if (owned.length >= 0xffff) throw new Error('Evidence archive exceeds the supported entry count');
  for (const [path] of owned) validateEvidencePath({ path });
  const abort = new AbortController();
  const output = createReadableZipOutput({ highWaterMarkBytes: 256 * 1024 });
  const directory = createMemoryZipCentralDirectoryStore();
  const writer = new StreamingZipWriter({
    output: output.sink,
    centralDirectoryStore: directory,
    compressionCodec: createWebZipCompressionCodec(),
  });
  const stream = createAbortableByteStream({
    stream: output.stream,
    signal: abort.signal,
    onCancel: () => abort.abort(new DOMException('Evidence export cancelled', 'AbortError')),
  });
  const produce = async (): Promise<void> => {
    try {
      for (const [path, content] of owned) {
        abort.signal.throwIfAborted();
        await writer.addFile({
          name: path,
          stream: createAbortableByteStream({ stream: content.stream(), signal: abort.signal, onCancel: undefined }),
          compression: 'deflate',
          modifiedAt: new Date(1980, 0, 1),
        });
      }
      abort.signal.throwIfAborted();
      await writer.finalize();
      await output.close();
    } catch (reason) {
      await output.abort({ reason }).catch(() => undefined);
    } finally {
      await directory.dispose();
    }
  };
  // Output.write awaits backpressure; cancellation also wakes the active input.
  void produce().catch(() => undefined);
  return stream;
}

/** Buffered adapter for consumers that must randomly inspect the archive.
 * User-facing downloads must use createEvidenceArchiveStream instead. */
export async function createEvidenceArchive({ files }: {
  files: ReadonlyMap<string, Blob>;
}): Promise<Blob> {
  return await new Response(createEvidenceArchiveStream({ files }), {
    headers: { 'Content-Type': 'application/zip' },
  }).blob();
}

/** Index once, decode one requested entry at a time, and retain no decoded body. */
export async function openEvidenceArchive({ blob }: { blob: Blob }): Promise<{
  reader: EvidenceArchiveReader; close(): Promise<void>;
}> {
  const zip = new StreamingZipReader({
    source: createBlobZipSource({ blob }),
    compressionCodec: createWebZipCompressionCodec(),
  });
  let closed = false;
  try {
    const entries = new Map<string, ZipArchiveEntry>();
    for await (const entry of zip.entries()) {
      if (entry.isDirectory) continue;
      validateEvidencePath({ path: entry.name });
      if (entry.isSymbolicLink || entries.has(entry.name)) throw new Error('Duplicate or unsupported Evidence archive entry');
      entries.set(entry.name, entry);
    }
    return {
      reader: {
        paths: [...entries.keys()],
        async read({ path, maximumBytes }) {
          if (closed) throw new Error('Evidence archive reader is closed');
          const entry = entries.get(path);
          if (entry === undefined) return undefined;
          // Refuse before opening/decompressing a newly bounded sidecar. The
          // shared ZIP reader also verifies actual bytes against this size.
          if (maximumBytes !== undefined && entry.uncompressedSize > maximumBytes) throw new Error('Evidence entry exceeds its read byte budget');
          const parts: Blob[] = [];
          for await (const chunk of iterateZipStreamChunks({ stream: await zip.openEntry({ entry }) })) {
            parts.push(new Blob([Uint8Array.from(chunk)]));
          }
          return new Blob(parts);
        },
      },
      async close() {
        closed = true;
        entries.clear();
        await zip.close();
      },
    };
  } catch (error) {
    await zip.close();
    throw error;
  }
}

